func Fail(t TestingT, failureMessage string, msgAndArgs ...interface{}) bool {

	message := messageFromMsgAndArgs(msgAndArgs...)

	if len(message) > 0 {
		t.Errorf("\r%s\r\tLocation:\t%s\n"+
			"\r\tError:%s\n"+
			"\r\tMessages:\t%s\n\r",
			getWhitespaceString(),
			CallerInfo(),
			indentMessageLines(failureMessage, 2),
			message)
	} else {
		t.Errorf("\r%s\r\tLocation:\t%s\n"+
			"\r\tError:%s\n\r",
			getWhitespaceString(),
			CallerInfo(),
			indentMessageLines(failureMessage, 2))
	}

	return false
}
